def choose_files(status_lines):
    allowed = {'.gitignore', 'README.md', 'src/study.py'}
    chosen = []
    seen = set()
    for line in status_lines:
        path = line[3:]
        if path in allowed and path not in seen:
            chosen.append(path)
            seen.add(path)
    return chosen
